g=np.array([[5,0,0,5,0],[5,0,0,5,0],[5,0,5,5,5],[5,5,5,0,0],[0,0,5,0,0],[0,0,5,5,5],[0,0,0,5,0],[5,5,5,5,0],[0,5,0,0,0],[0,5,0,0,0],[0,5,5,5,0],[0,0,0,5,0],[0,5,5,5,5],[5,5,0,0,0],[0,5,0,0,0]])
out=np.array([[5,0,0,5,0],[5,0,0,5,0],[5,0,5,5,5],[5,5,5,0,0],[0,0,5,0,0],[0,0,5,5,5],[0,0,0,5,8],[5,5,5,5,8],[0,5,8,8,8],[0,5,8,8,8],[0,5,5,5,8],[0,0,0,5,8],[0,5,5,5,5],[5,5,0,0,0],[7,5,0,0,0]])
H,W=g.shape
# connected components of 0s (4-conn)
lab=-np.ones((H,W),int); cid=0
import collections
for i in range(H):
  for j in range(W):
    if g[i,j]==0 and lab[i,j]==-1:
      q=collections.deque([(i,j)]); lab[i,j]=cid
      while q:
        a,b=q.popleft()
        for da,db in((1,0),(-1,0),(0,1),(0,-1)):
          na,nb=a+da,b+db
          if 0<=na<H and 0<=nb<W and g[na,nb]==0 and lab[na,nb]==-1:
            lab[na,nb]=cid; q.append((na,nb))
      cid+=1
comps={}
for i in range(H):
  for j in range(W):
    if g[i,j]==0: comps.setdefault(lab[i,j],[]).append((i,j))
for c,cells in comps.items():
  touch=any(i==0 or i==H-1 or j==0 or j==W-1 for i,j in cells)
  ovals=set(out[i,j] for i,j in cells)
  print(c,len(cells),'touch',touch,'outvals',ovals, cells if len(cells)<25 else '')
print('7 at',[ (i,j) for i in range(H) for j in range(W) if out[i,j]==7])
print('8 at',[ (i,j) for i in range(H) for j in range(W) if out[i,j]==8])

def feat(i,j):
    o=sum(1 for da,db in((1,0),(-1,0),(0,1),(0,-1)) if 0<=i+da<H and 0<=j+db<W and g[i+da,j+db]==5)
    d=sum(1 for da,db in((1,1),(1,-1),(-1,1),(-1,-1)) if 0<=i+da<H and 0<=j+db<W and g[i+da,j+db]==5)
    return o,d
from collections import Counter
c=Counter()
for i in range(H):
  for j in range(W):
    if g[i,j]==0:
      c[(feat(i,j),int(out[i,j]))]+=1
for k in sorted(c): print(k,c[k])

